class AlgorithmTemplate:

    def build(self, input_data, ctx):
        shots = input_data.get("shots", 1024)
        qasm = """OPENQASM 2.0;
include "qelib1.inc";
qreg q[4];
creg c[2];
h q[0]; h q[1];
cx q[0],q[2]; cx q[1],q[2]; cx q[0],q[3];
h q[0]; h q[1];
measure q[0] -> c[0];
measure q[1] -> c[1];"""
        backend = ctx.get("backend_id", "vortex-noiseless")
        provider = "vortex"
        if "ibm" in backend:
            provider = "ibm"
        elif "ionq" in backend:
            provider = "ionq"
        return {
            "type": "circuit",
            "provider": provider,
            "backend_id": backend,
            "qasm_code": qasm,
            "shots": shots,
        }

    def interpret(self, raw_result, input_data):
        counts = raw_result.get("counts", {})
        total = sum(counts.values()) if counts else 0
        valid = ["00", "11"]
        valid_count = sum(counts.get(v, 0) for v in valid)
        valid_prob = valid_count / total if total > 0 else 0
        top = sorted(counts.items(), key=lambda x: -x[1])[:4]
        return {
            "counts": counts,
            "hidden_period": "11",
            "valid_measurements": valid,
            "valid_probability": round(valid_prob, 4),
            "top_outcomes": [{"state": s, "count": c} for s, c in top],
            "note": "Simons algorithm found period s=11. Valid measurements (y.s=0 mod 2): 00, 11. Observed " + str(round(valid_prob * 100, 1)) + "% valid outcomes out of " + str(total) + " shots.",
        }

